import type { CurrencyCodeType } from '../../../types/currency';

/**
 * Indicates the type of data that document metadata can have.
 *
 * - 'money': Used for monetary values.
 * - 'date': Used for date values.
 * - 'list': Used for lists of strings.
 * - 'ref': Used for references to objects or entities.
 * - 'string': Used for string values.
 */
export type DataType = 'money' | 'date' | 'list' | 'ref' | 'string';

export type EntityType = 'company' | 'person';

export type MetadataKeyNameType =
  | 'contract_type'
  | 'amount'
  | 'start_date'
  | 'end_date'
  | 'party'
  | 'counterparty';

export const ORGANIZATION_ENTITY = {
  person: 'Organization::Person',
  company: 'Organization::Company',
} as const satisfies Record<EntityType, string>;

export type MetadataRefType = (typeof ORGANIZATION_ENTITY)[keyof typeof ORGANIZATION_ENTITY];

export type MetadataExtras = {
  refId?: number;
  refType?: MetadataRefType;
  currency?: CurrencyCodeType;
};

export type DataValidationType = {
  /** Unique identifier of the user who is validating the metadata. */
  userId?: number;
  /** ISO date string representing when the metadata was validated. */
  validatedAt?: string;
};

export interface DocumentMetadata {
  /** Unique identifier for the document metadata. */
  id: number;
  /** Universally unique identifier for the document metadata. */
  uuid: string;
  /** Key name of the metadata field. */
  keyName: MetadataKeyNameType;
  /** Data type of the metadata value. */
  dataType: DataType;
  /** Indicates whether the metadata was generated by AI. */
  aiGenerated?: boolean;
  /** Label of the metadata field. */
  label?: string;
  /** Value of the metadata field as a string. */
  value?: string;
  /** Additional metadata information. */
  extras?: MetadataExtras;
  /** ISO date string representing when the metadata was created. */
  createdAt?: string;
  /** ISO date string representing when the metadata was last updated. */
  updatedAt?: string;
  /** Indicates whether the metadata is currently being validated by a user. */
  dataValidation?: DataValidationType;
}

export interface DocumentMetadataPayload {
  /** Unique identifier for the document metadata. */
  id: number;
  /** Universally unique identifier for the document metadata. */
  metadatum_uuid: string;
  /** Key name of the metadata field. */
  key_name: MetadataKeyNameType;
  /** Data type of the metadata value. */
  data_type: DataType;
  /** Indicates whether the metadata was generated by AI. */
  ai_generated?: boolean;
  /** Value of the metadata field as a string. */
  value?: string;
  /** Additional metadata information. */
  extras?: MetadataExtras;
  /** ISO date string representing when the metadata was created. */
  created_at?: string;
  /** ISO date string representing when the metadata was last updated. */
  updated_at?: string;
  /** Indicates whether the metadata is currently being validated by a user. */
  data_validation?: DataValidationType;
}

export interface GroupedDocumentMetadata extends Omit<DocumentMetadata, 'value'> {
  values: string[];
}
